<template><view class="page"><nav-bar title="题库组详情" :showBack="true" placeholder/><view class="header"><text class="name">{{bank.name}}</text><text>{{bank.bankType||'自定义'}} · {{bank.questionCount||0}}道题</text><text>{{bank.description||'暂无说明'}}</text></view><view v-if="loading" class="state">加载中...</view><view v-else-if="!questions.length" class="state">题库组中暂无题目</view><view v-for="q in questions" :key="q.id" class="card"><view class="tags"><text>{{q.questionType}}</text><text>{{q.difficulty}}</text></view><text class="content">{{q.content}}</text><view class="actions"><text @click="detail(q.id)">查看详情</text><text class="danger" @click="remove(q)">移除</text></view></view></view></template>
<script>import NavBar from '@/components/nav-bar/nav-bar.vue';import{getPaperBank,listQuestions,removeQuestionFromBank}from'@/api/paper.js';export default{components:{NavBar},data(){return{id:null,bank:{},questions:[],loading:false}},onLoad(q){this.id=q.id;this.load()},methods:{async load(){this.loading=true;try{const[b,q]=await Promise.all([getPaperBank(this.id),listQuestions(this.id)]);this.bank=b.data||{};this.questions=q.data||[]}finally{this.loading=false}},detail(id){uni.navigateTo({url:`/subpackage_ai/paperQuestionDetail/paperQuestionDetail?questionId=${id}`})},remove(q){uni.showModal({title:'确认移除？',content:'仅从当前题库组移除，不会删除原题。',success:async r=>{if(r.confirm){await removeQuestionFromBank(this.id,q.id);this.questions=this.questions.filter(x=>x.id!==q.id);this.bank.questionCount=this.questions.length}}})}}}</script>
<style scoped>.page{min-height:100vh;background:#f5f8fc;padding:24rpx}.header,.card{background:#fff;border-radius:18rpx;padding:24rpx;margin-bottom:16rpx}.header text{display:block;color:#7e8a9c;margin-top:10rpx}.header .name{font-size:32rpx;font-weight:700;color:#26354c}.tags text{background:#eaf2ff;color:#4775e5;padding:6rpx 12rpx;border-radius:10rpx;margin-right:10rpx}.content{display:block;line-height:1.6;margin:18rpx 0}.actions{text-align:right}.actions text{color:#4775e5;margin-left:28rpx}.actions .danger{color:#df6565}.state{text-align:center;color:#9ca7b6;padding:100rpx}</style>
